import time

def retry_with_backoff(fn, max_attempts=3):
    """
    Call `fn` up to `max_attempts` times, returning the result on success.
    If all attempts fail, re‑raise the last exception without sleeping
    after the final attempt.
    """
    for attempt in range(max_attempts):
        try:
            return fn()
        except Exception as exc:
            # If this was the last allowed attempt, re‑raise immediately.
            if attempt == max_attempts - 1:
                raise
            # Otherwise, wait before retrying.
            time.sleep(0.01 * (attempt + 1))
