import time

def retry_with_backoff(fn, max_attempts=3):
    """
    Call `fn` up to `max_attempts` times, retrying with a short back‑off
    between attempts. If all attempts fail, re‑raise the last exception
    without sleeping after it.
    """
    attempt = 1
    while attempt <= max_attempts:
        try:
            return fn()
        except Exception:
            if attempt == max_attempts:
                raise
            time.sleep(0.01 * attempt)
            attempt += 1
