def find_rotation_point(arr):
    """Index of the smallest element in a rotated sorted array."""
    if not arr:
        return -1

    lo, hi = 0, len(arr) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        # If the middle element is greater than the last element,
        # the smallest element is in the right half.
        if arr[mid] > arr[hi]:
            lo = mid + 1
        else:
            hi = mid
    return lo
