def binary_search_first(arr, target):
    """Return the index of the first occurrence of target, or -1."""
    lo, hi = 0, len(arr) - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            ans = mid
            hi = mid - 1  # keep searching left to find first
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return ans
