def is_balanced(s):
    """
    Return True if the string `s` contains only the characters
    '(', ')', '[', ']', '{', '}' and they are correctly nested
    and matched.  Any other characters are ignored.
    """
    # Mapping of closing to opening brackets
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []

    for c in s:
        if c in '([{':
            stack.append(c)
        elif c in ')]}':
            if not stack or stack[-1] != pairs[c]:
                return False
            stack.pop()

    return not stack
```

