from freight import shipping_cost

def total_with_shipping(subtotal, weight_kg):
    """
    Calculate the total cost including shipping.

    Shipping is applied only when the subtotal is strictly greater than $50.
    The subtotal is rounded to two decimal places. Shipping cost is also
    rounded to two decimal places before adding to the subtotal.
    """
    if subtotal > 50:
        return round(subtotal + shipping_cost(subtotal, weight_kg), 2)
    return round(subtotal, 2)
