def parse_bool(value):
    """
    Parse a value into a boolean.

    Accepts bool, int, and str. True/1/'true'/'yes'/'1' (case‑insensitive) are True;
    False/0/'false'/'no'/'0' are False. Other strings raise ValueError.
    """
    # Handle boolean values directly
    if isinstance(value, bool):
        return value

    # Handle integer values
    if isinstance(value, int):
        if value == 1:
            return True
        if value == 0:
            return False
        raise ValueError(f"Invalid integer value for boolean: {value}")

    # Handle string values
    if isinstance(value, str):
        val = value.strip().lower()
        if val in ("true", "yes", "1"):
            return True
        if val in ("false", "no", "0"):
            return False
        raise ValueError(f"Invalid string value for boolean: {value}")

    # Unsupported types
    raise ValueError(f"Unsupported type for boolean: {type(value).__name__}")
